INSERT INTO ownership_controls(control_type,title,description,applicability,risk_level,approval_route,evidence_required) SELECT 'Reserved Matter','Change of control / major ownership restructuring','Any transaction that materially changes control, founder protection, voting power or ownership of a strategic group entity requires formal governance approval and legal review.','Group-wide','Critical','Board + applicable shareholder approval + legal review','Executed instrument, cap table, board/shareholder resolutions and statutory filings where applicable' WHERE NOT EXISTS (SELECT 1 FROM ownership_controls WHERE title='Change of control / major ownership restructuring');
INSERT INTO ownership_controls(control_type,title,description,applicability,risk_level,approval_route,evidence_required) SELECT 'Protected Interest','Indigenous and community ownership safeguard','Where land, customary rights, community assets or indigenous interests are legitimately involved, no transfer, dilution, encumbrance or restructuring should proceed without documented rights review and the approvals required by applicable law and agreements.','Asset/entity-specific','Critical','Board + community/stewardship review + applicable legal/regulatory approvals','Title/right evidence, agreements, consultation record and executed approvals' WHERE NOT EXISTS (SELECT 1 FROM ownership_controls WHERE title='Indigenous and community ownership safeguard');
INSERT INTO ownership_controls(control_type,title,description,applicability,risk_level,approval_route,evidence_required) SELECT 'Control','Beneficial ownership / PSC verification','Beneficial ownership and persons with significant control must be verified and maintained against the applicable jurisdictional filing requirements before being treated as complete.','Group-wide','High','Company Secretary + Compliance + legal review','Identity evidence, ownership chain and applicable statutory filing evidence' WHERE NOT EXISTS (SELECT 1 FROM ownership_controls WHERE title='Beneficial ownership / PSC verification');
INSERT INTO ownership_controls(control_type,title,description,applicability,risk_level,approval_route,evidence_required) SELECT 'Transfer Control','Share transfer and issuance control','Issuance, transfer, redemption or cancellation of shares must be checked against constitutional documents, shareholder agreements, reserved matters and applicable law before execution.','Group-wide','High','Board / shareholders as applicable + Company Secretary','Instrument, resolutions, updated register and filing evidence where required' WHERE NOT EXISTS (SELECT 1 FROM ownership_controls WHERE title='Share transfer and issuance control');