CREATE TABLE IF NOT EXISTS ownership_governance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_name text NOT NULL, owner_type text NOT NULL, jurisdiction text NOT NULL DEFAULT 'Nigeria', entity_name text NOT NULL DEFAULT 'OSANVAULT AFRICA LTD', share_class text NOT NULL, shares numeric NOT NULL DEFAULT 0, voting_rights text, beneficial_owner_name text, psc_status text NOT NULL DEFAULT 'Needs Review', indigenous_community_status text NOT NULL DEFAULT 'Not Applicable / Not Assessed', transfer_status text NOT NULL DEFAULT 'Unrestricted Subject to Constitution and Law', reserved_rights text, verification_status text NOT NULL DEFAULT 'Unverified', evidence_reference text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ownership_controls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), control_type text NOT NULL, title text NOT NULL, description text NOT NULL, applicability text NOT NULL DEFAULT 'Group-wide', risk_level text NOT NULL DEFAULT 'High', status text NOT NULL DEFAULT 'Active', approval_route text, evidence_required text, created_at timestamptz NOT NULL DEFAULT now());
